# -*- coding: utf-8 -*-
from pathlib import Path
import json,html
O=Path(__file__).resolve().parents[2]/'assets/style-a'
manifest=json.loads((O/'audio/manifest.json').read_text())
ui=[('main-menu','主菜单'),('level-select','关卡选择'),('object-select','物体选择栏'),('result-success','成功结算'),('result-failure','失败结算'),('settings','设置面板'),('room-scan','空间扫描'),('tutorial','新手引导')]
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Space Bend · 素材审阅</title><style>*{box-sizing:border-box}body{margin:0;background:#0b1218;color:#eaf2f7;font-family:"PingFang SC","Helvetica Neue",sans-serif}main{max-width:1440px;margin:auto;padding:52px}header{display:flex;justify-content:space-between;border-bottom:1px solid #405867;padding-bottom:30px}h1{font-size:40px;font-weight:500;letter-spacing:2px;margin:12px 0}h2{font-size:26px;font-weight:400;margin:56px 0 22px}h3{font-size:16px;font-weight:400}p{color:#93a9b8;line-height:1.8}small{color:#9ce5f4;letter-spacing:2px}.hero{width:100%;margin-top:28px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:28px}.grid img{width:100%;height:auto}.bar{display:flex;gap:12px;margin:24px 0}button,a.action{background:#1b303d;border:1px solid #608598;border-radius:0;color:#eaf2f7;padding:12px 22px;cursor:pointer;clip-path:polygon(8px 0,100% 0,100% calc(100% - 8px),calc(100% - 8px) 100%,0 100%,0 8px);font:inherit;text-decoration:none}button:hover,a.action:hover{background:#365968}button.active{color:#9ce5f4;border-color:#9ce5f4}audio{width:100%;height:36px}.audio-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.audio-item{padding:16px 0;border-top:1px solid #344b59}.status{color:#e9b66e}object{width:100%;aspect-ratio:1.5}code{font-size:13px;color:#9ce5f4}.note{padding:14px 0;border-top:1px solid #344b59}@media(max-width:800px){main{padding:24px}.grid,.audio-grid{grid-template-columns:1fr}header{display:block}h1{font-size:30px}}</style><main><header><div><small>SB / ASSET REVIEW · 02</small><h1>引力实验室</h1><p>空间折跃 / Space Bend · 风格 A · 素材审阅包</p></div><div><p>钛灰金属 / 冰蓝引力光 / 琥珀警示</p><p class="status">第三步 · 原生 Spatial 项目已开发 · 运行证据见交付目录</p></div></header><img class="hero" src="reference/gravity-lab-keyframe.png" alt="引力实验室视觉参考"><p>视觉参考图，由 imagegen 生成；不是设备运行截图，也不是可用三维模型。</p><h2>01 / 自定义空间 UI</h2><p>切角轮廓、仪表刻度与六种物体示意图标。全部面板均提供三语 SVG 源文件；界面中的记录、星级和物体参数为审阅示例。</p><div class="bar"><button data-lang="zh-Hans" class="active">简体中文</button><button data-lang="zh-Hant">繁體中文</button><button data-lang="en">English</button></div><div class="grid">'''
for name,label in ui:page+=f'<article><h3>{label}</h3><img data-ui="{name}" src="ui/{name}.zh-Hans.svg" alt="{label}"><a class="action" data-download="{name}" href="ui/{name}.zh-Hans.svg" download>SVG 源文件</a></article>'
page+='</div><h2>02 / 交互元素</h2><img style="width:100%" src="ui/control-library.svg" alt="按钮五态、进度条、星级和瞄准标记"><p>附 10 种独立交互图标和两种星级 SVG。物体示意图标用于 UI，不代替三维模型。</p><h2>03 / 虫洞动态方向</h2><object type="image/svg+xml" data="vfx/wormhole-cycle.svg"></object><p>8 秒视觉方向循环：闭合、引力吸入、收缩消失。另附真实 GLB 动画源文件：Portal_Close / Portal_Suction / Portal_Collapse。此处为矢量动态素材预览，运行时使用真实平面锚定的动态轮廓与空间音频；这里展示素材参考。</p><a class="action" href="vfx/wormhole-reference.glb" download>下载虫洞 GLB 动画参考资产</a><h2>04 / 音频试听</h2><h3>深邃科技环境音 · 32 秒立体声循环</h3><audio controls preload="none" src="audio/ambient-lab-loop.wav"></audio><div class="audio-grid">'
labels={'draw-loop':'绘制笔触','portal-close':'虫洞闭合','suction-loop':'虫洞吸入（单声道声源）','object-flight':'物体飞行','plane-impact':'平面碰撞','success':'成功提示','failure':'失败提示','portal-collapse':'虫洞收缩'}
for a in manifest['sfx']:page+=f'<article class="audio-item"><h3>{labels[Path(a["file"]).stem]}</h3><audio controls preload="none" src="audio/{a["file"]}"></audio></article>'
page+='</div><p>原创合成音频。吸入声已提供单声道循环源文件；已接入 PICO Spatial Audio 距离衰减；真实头显听感仍待实测。</p><h2>05 / 三语播报</h2><p>中文、英文各 12 条，共 24 个语音文件；简体与繁体中文共用简体语音，显示文案分别保留，覆盖扫描、绘制、选择、放置、闭环、失败、移动、删除与跟踪丢失。当前为本机合成播报。</p><div class="audio-grid">'
for lang,label in [('zh-Hans','简体中文'),('zh-Hant','繁體中文'),('en','English')]:
 voice_lang='zh-Hans' if lang=='zh-Hant' else lang
 texts=json.loads((O/'locales'/f'{lang}.json').read_text())
 page+=f'<section><h3>{label}</h3>'
 for a in manifest['voice']:
  if a['language']==voice_lang:page+=f'<article class="audio-item"><p>{html.escape(texts[a["id"]])}</p><audio controls preload="none" src="audio/{a["file"]}"></audio></article>'
 page+='</section>'
page+='</div><h2>06 / 三维模型制作状态</h2><a class="action" href="models-preview.html">打开可旋转三维预览 / 下载模型</a><img style="width:100%;margin-top:24px" src="previews/models-board.png" alt="六种真实模型预览"><div id="model-status"><p class="status">六种物体已提供真实 GLB 网格与 PBR 材质。当前为程序化硬表面初稿，写实细节尚需审阅。</p></div><p class="note">此页保留素材与示例文案预览，实际运行 APK、截图与验证说明位于项目 output 和 docs/delivery 目录。</p></main><script>document.querySelectorAll("[data-lang]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-lang]").forEach(a=>a.classList.toggle("active",a===b));document.querySelectorAll("[data-ui]").forEach(i=>i.src=`ui/${i.dataset.ui}.${b.dataset.lang}.svg`);document.querySelectorAll("[data-download]").forEach(i=>i.href=`ui/${i.dataset.download}.${b.dataset.lang}.svg`)});</script></html>'
(O/'preview.html').write_text(page)
# Standalone UI proof sheet for inline delivery, separate from the full review gallery.
board='<!doctype html><meta charset="utf-8"><style>*{box-sizing:border-box}body{margin:0;background:#0b1218;color:#eaf2f7;font-family:"PingFang SC",sans-serif;padding:40px}h1{font-size:30px;margin:0 0 8px}p{color:#93a9b8;font-size:16px;margin:0 0 24px}.g{display:grid;grid-template-columns:1fr 1fr;gap:20px}img{width:100%;display:block}h2{font-size:17px;font-weight:400;margin:0 0 8px}</style><h1>SPACE BEND / 引力实验室</h1><p>第二步 · 自定义 UI 素材稿 · 简体中文 · 示例数据</p><div class="g">'
for name,label in ui:board+=f'<div><h2>{label}</h2><img src="../ui/{name}.zh-Hans.svg"></div>'
board+='</div>'; (O/'previews/ui-board.html').write_text(board)
print('Review gallery created:',O/'preview.html')
